draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // window
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.strokeRect(W/2 - 50, H/2 - 50, 100, 100);

  // dog
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 70, H/2 - 20, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 70, H/2 - 10);
  ctx.lineTo(W/2 - 70, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 70, H/2);
  ctx.lineTo(W/2 - 90, H/2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 70, H/2);
  ctx.lineTo(W/2 - 50, H/2 + 10);
  ctx.stroke();

  // barking mouth
  ctx.beginPath();
  ctx.arc(W/2 - 70, H/2 - 10, 5, 0, Math.PI + Math.sin(t) * Math.PI);
  ctx.stroke();

  // mailman
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 70, H/2 - 20, 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 + 70, H/2 - 10);
  ctx.lineTo(W/2 + 70, H/2 + 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 70, H/2);
  ctx.lineTo(W/2 + 50, H/2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 70, H/2);
  ctx.lineTo(W/2 + 90, H/2 + 10);
  ctx.stroke();

  // mailman moving away
  ctx.translate(W/2 + 70, H/2);
  ctx.rotate(Math.sin(t) * 0.1);
  ctx.beginPath();
  ctx.moveTo(0, 0);
  ctx.lineTo(-10, 10);
  ctx.stroke();
  ctx.setTransform(1, 0, 0, 1, 0, 0);

  ctx.restore();
}
